  '.stage{min-height:100dvh;display:grid;place-items:center;padding:clamp(18px,4vw,52px);overflow:clip}.scene{width:min(980px,100%);display:grid;gap:22px}.scene-copy{display:grid;gap:7px}.scene-copy span{color:var(--accent);font:700 11px ui-monospace,monospace;letter-spacing:.16em;text-transform:uppercase}.scene-copy h1{max-width:780px;margin:0;font-size:clamp(28px,5vw,56px);line-height:1.02;letter-spacing:-.04em}.scene-copy p{max-width:720px;margin:0;color:var(--muted);font-size:14px;line-height:1.55}.status{min-height:22px;margin:0;color:var(--muted);font-size:13px}.primary-action,.pay-form button,.checkout-fields button,.simple-login button,.v5-fields>button,.otp-box>button,.v3-form>button,.upload-card>button{border-color:color-mix(in srgb,var(--accent) 70%,var(--line));background:var(--accent);color:#06101e;font-weight:800}.text-action,[data-auth]{border:0;background:transparent;color:var(--accent);text-decoration:underline;text-underline-offset:4px}',
  'label{display:grid;gap:6px;color:var(--muted);font-size:11px}h2{margin:0;font-size:22px}.scene [hidden]{display:none!important}',
  '.tabs-scene{--tab:0}.light-tabs{position:relative;display:grid;grid-template-columns:repeat(4,1fr);padding:8px;border:1px solid var(--line);border-radius:14px;background:var(--panel)}.light-tabs button{position:relative;z-index:1;border:0;background:transparent;color:var(--muted)}.light-tabs button[aria-selected=true]{color:white}.light-rail{position:absolute;left:8px;bottom:7px;width:calc((100% - 16px)/4);height:3px;background:var(--accent);transform:translateX(calc(var(--tab)*100%));transition:transform calc(.48s/var(--speed)) cubic-bezier(.2,.8,.2,1)}.light-rail::before{content:"";position:absolute;inset:-8px 18% -8px;background:color-mix(in srgb,var(--accent) 28%,transparent);opacity:.75}.tab-panel{min-height:210px;padding:28px;border:1px solid var(--line);border-radius:14px;background:var(--panel);transition:opacity .18s}.tab-panel b{font-size:24px}.tab-panel p{color:var(--muted)}',
  '.order-card{display:grid;gap:18px;padding:24px;border:1px solid var(--line);border-radius:18px;background:var(--panel)}.route{position:relative;height:190px;overflow:clip;border:1px solid var(--line);border-radius:14px;background:#0d141d}.road{position:absolute;bottom:45px;width:50%;height:58px;background:#222b35;transition:transform calc(.65s/var(--speed)) cubic-bezier(.2,.8,.2,1)}.road::after{content:"";position:absolute;left:10%;right:10%;top:28px;border-top:2px dashed #788596}.road-a{left:0;transform:translateX(100%)}.road-b{right:0;transform:translateX(-100%)}.depot,.home{position:absolute;bottom:103px;padding:8px 10px;border:1px solid var(--line);background:#121c28;font:700 9px ui-monospace,monospace}.depot{left:6%}.home{right:6%}.van{position:absolute;left:10%;bottom:74px;width:122px;height:48px;border:2px solid #f1f5f9;background:#dbe8f5;transform:translateX(-180%);transition:transform calc(1.8s/var(--speed)) cubic-bezier(.35,.05,.2,1)}.van::after{content:"";position:absolute;right:-34px;bottom:0;border-style:solid;border-width:0 0 46px 34px;border-color:transparent transparent #dbe8f5 transparent}.van i{position:absolute;inset:8px auto 8px 42px;width:28px;background:var(--accent)}.van b{position:absolute;left:8px;top:12px;color:#111}.van span{position:absolute;bottom:-12px;width:22px;height:22px;border:5px solid #9aa7b6;border-radius:50%;background:#111}.van span:first-of-type{left:17px}.van span:last-child{right:-25px}.order-scene[data-state=ordered] .road,.order-scene[data-state=complete] .road{transform:translateX(0)}.order-scene[data-state=ordered] .van{transform:translateX(85%)}.order-scene[data-state=complete] .van{transform:translateX(570%)}',
  '.auth-card{position:relative;min-height:390px;display:grid;grid-template-columns:1fr 1fr;overflow:clip;border:1px solid var(--line);border-radius:18px;background:#f3f0e9;color:#132019}.auth-pane{display:grid;align-content:center;gap:14px;padding:34px;transition:transform calc(.55s/var(--speed)) cubic-bezier(.2,.8,.2,1),opacity .16s}.auth-pane input{background:transparent;color:#132019;border-color:#9ca79d}.auth-pane>button:not(.text-action){background:#113e31;color:white;border-color:#113e31}.auth-blade{position:absolute;z-index:3;inset:0 auto 0 0;width:50%;display:grid;align-content:center;padding:38px;background:#073a2e;color:white;transform:translateX(100%);transition:transform calc(.68s/var(--speed)) cubic-bezier(.2,.8,.2,1);pointer-events:none}.auth-blade b{color:#efc66b;letter-spacing:.16em}.blade-scene[data-state=signup] .auth-blade{transform:translateX(0)}.blade-scene[data-state=signup] .pane-signin{transform:translateX(100%);opacity:0}.blade-scene[data-state=signin] .pane-signup{transform:translateX(-100%);opacity:0}',
  '.payment-grid,.checkout-shell,.v3-shell{display:grid;grid-template-columns:minmax(280px,.9fr) minmax(300px,1.1fr);gap:18px;padding:22px;border:1px solid var(--line);border-radius:18px;background:#eef4fb;color:#0c1a2a}.card-preview,.mini-card{align-self:center;min-height:190px;display:grid;align-content:space-between;padding:24px;border:2px solid #8bb4e8;border-radius:17px;background:#dfefff;transition:transform calc(.7s/var(--speed)) cubic-bezier(.2,.8,.2,1),opacity .2s}.card-preview span,.mini-card span{font:700 10px ui-monospace,monospace;letter-spacing:.18em}.card-preview b,.mini-card b{font:700 18px ui-monospace,monospace}.pay-form,.checkout-fields,.v3-form{display:grid;align-content:center;gap:14px}.pay-form>div{display:grid;grid-template-columns:1fr 1fr;gap:10px}.payment-scene[data-state=loading] .card-preview{transform:translateX(26%) scale(.94);opacity:.55}.payment-scene[data-state=success] .card-preview{transform:translateX(52%);opacity:0}.payment-scene[data-state=error] .pay-form input{border-color:var(--danger)}',
  '.room,.lamp-room{position:relative;min-height:420px;display:grid;place-items:center;overflow:clip;border:1px solid var(--line);border-radius:18px;background:#07100c;transition:background-color .2s}.lamp-switch{position:absolute;left:10%;top:17%;width:104px;height:170px;border:0;background:transparent}.shade{position:absolute;left:15px;top:0;width:74px;height:54px;border-radius:50% 50% 14px 14px;background:#e6b96b}.cord{position:absolute;left:51px;top:49px;width:2px;height:86px;background:#e6b96b}.pull{position:absolute;left:43px;top:129px;width:18px;height:18px;border:2px solid #e6b96b;border-radius:50%;transition:transform .18s}.lamp-switch:active .pull{transform:translateY(8px)}.panda{position:absolute;left:52%;top:20px;width:112px;height:92px;border:2px solid #d8e0dd;border-radius:48% 48% 42% 42%;background:white;transform:translateX(-50%)}.panda .ear{position:absolute;top:-17px;width:35px;height:35px;border-radius:50%;background:#171c22}.panda .e1{left:3px}.panda .e2{right:3px}.panda .eye{position:absolute;top:32px;width:17px;height:22px;border-radius:50%;background:#111;transition:transform .18s}.panda .eye1{left:27px}.panda .eye2{right:27px}.panda.is-private .eye{transform:scaleY(.12)}.panda b{position:absolute;left:50%;bottom:17px;width:20px;height:10px;border-bottom:3px solid #111;border-radius:50%;transform:translateX(-50%)}.login-panel,.simple-login{width:min(360px,80%);display:grid;gap:13px;padding:24px;border:1px solid #285241;border-radius:16px;background:#0a1b14;transition:opacity .18s,transform calc(.48s/var(--speed)) cubic-bezier(.2,.8,.2,1)}.panda-scene[data-state=off] .login-panel,.lamp-scene[data-state=off] .simple-login{opacity:.08;transform:translateY(24px);pointer-events:none}.panda-scene[data-state=on] .room,.panda-scene[data-state=loading] .room,.panda-scene[data-state=success] .room,.lamp-scene[data-state=on] .lamp-room,.lamp-scene[data-state=success] .lamp-room{background:#102218}.panda-scene[data-state=success] .login-panel,.lamp-scene[data-state=success] .simple-login{border-color:var(--success)}',
