  "function clearTimers(){while(timers.length)clearTimeout(timers.pop())}",
  "function setStatus(text){if(statusNode)statusNode.textContent=text||''}",
  "function updateGated(state){const gated=document.querySelector('[data-gated]');if(!gated)return;const enabled=state!=='off';gated.toggleAttribute('inert',!enabled);gated.setAttribute('aria-hidden',String(!enabled));gated.querySelectorAll('input,button').forEach(el=>{el.disabled=!enabled});if(enabled&&document.activeElement?.matches('[data-lamp]'))gated.querySelector('input')?.focus()}",
  "function setState(state){scene.dataset.state=state;setStatus(stateMessages[state]||state);updateGated(state);const label=document.querySelector('[data-action-label]');if(label)label.textContent=state==='complete'?'Заказ отправлен':state==='ordered'?'Готовим маршрут':'Подтвердить заказ'}",
  "function play(){clearTimers();const phases=DEMO_PHASES;const finish=()=>setState(phases[phases.length-1][1]);if(reduce){setState(phases[0][1]);timers.push(setTimeout(finish,150));return}phases.forEach(([at,state])=>timers.push(setTimeout(()=>setState(state),at*1000/speed)))}",
  "function seek(value){clearTimers();const t=Math.max(0,Number(value)||0);let state=DEMO_PHASES[0][1];for(const phase of DEMO_PHASES)if(t>=phase[0])state=phase[1];setState(state)}",
  "function setAuth(mode){setState(mode);document.querySelectorAll('[data-auth]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.auth===mode)));const signin=document.querySelector('.pane-signin,.cloud-signin');const signup=document.querySelector('.pane-signup,.cloud-signup');if(signin){signin.toggleAttribute('inert',mode!=='signin');signin.setAttribute('aria-hidden',String(mode!=='signin'))}if(signup){signup.toggleAttribute('inert',mode!=='signup');signup.setAttribute('aria-hidden',String(mode!=='signup'))}const title=document.querySelector('[data-v5-title]');if(title)title.textContent=mode==='signup'?'Регистрация':'Вход'}",
  "function formatCard(value){const digits=String(value||'').replace(/\\D/g,'').slice(0,16);return (digits||'4242424242424242').replace(/(.{4})/g,'$1 ').trim()}",
  "function animateToTarget(source,target,label){if(reduce){setStatus(label);return Promise.resolve()}const a=source.getBoundingClientRect(),b=target.getBoundingClientRect();const token=document.createElement('span');token.className=DEMO_ID==='fly-to-cart'?'fly-token':'delete-token';token.textContent=DEMO_ID==='fly-to-cart'?'EF':'×';token.style.left=a.left+'px';token.style.top=a.top+'px';document.body.append(token);const animation=token.animate([{transform:'translate(0,0)',opacity:1},{transform:'translate('+(b.left-a.left)+'px,'+(b.top-a.top)+'px) rotate(180deg)',opacity:.65},{transform:'translate('+(b.left-a.left)+'px,'+(b.top-a.top)+'px) rotate(360deg) scale(.5)',opacity:0}],{duration:760/speed,easing:'cubic-bezier(.2,.8,.2,1)'});return animation.finished.finally(()=>{token.remove();setStatus(label)})}",
  "document.addEventListener('click',event=>{",
  " const primary=event.target.closest('[data-primary]');if(primary){if(DEMO_ID==='login-v5'){const email=document.querySelector('[data-email]')?.value||'';const password=document.querySelector('[data-password]')?.value||'';if(!/^\\S+@\\S+\\.\\S+$/.test(email)||password.length<8){setState('error');return}}play()}",
  " const auth=event.target.closest('[data-auth]');if(auth)setAuth(auth.dataset.auth);",
  " const lamp=event.target.closest('[data-lamp]');if(lamp){const on=scene.dataset.state==='off';lamp.setAttribute('aria-pressed',String(on));setState(on?'on':'off')}",
  " const tab=event.target.closest('[data-tab]');if(tab){const index=Number(tab.dataset.tab);scene.style.setProperty('--tab',String(index));document.querySelectorAll('[data-tab]').forEach((item,i)=>{item.setAttribute('aria-selected',String(i===index));item.tabIndex=i===index?0:-1});const titles=['Обзор','Проекты','Команда','Доступ'];const copies=['Ключевые события и состояние пространства.','Активные задачи и последние сборки.','Люди, агенты и доступные роли.','Разрешения, ключи и журнал подтверждений.'];document.querySelector('[data-tab-title]').textContent=titles[index];document.querySelector('[data-tab-copy]').textContent=copies[index];setState('active')}",
